/**
 * context.js — the 1904 context city (T-2477): faded stand-ins for every part of the
 * map that is not yet built, so Prairie Avenue reads in full colour against a city
 * that is plainly a sketch of what might be there.
 *
 * WHAT IT DRAWS, from `data/context/<scene>.json` (generated by
 * tools/build_context_1904.py): rectangles read off the Sanborn 1911 sheets on the
 * Indiana and Calumet faces and the cross-street lots, and a projected city past the
 * sheets' edges, each a box with a flat roof, a gable or a pyramid, its walls painted
 * with storeys, windows and doors (the facade, T-2833); and trees, which since T-2833
 * are the parkway's own grown elms (street-trees.js draws them: `treeStems`). That
 * file says which stand-in is read and which is projected, and by what
 * rule every height, roof and colour was chosen (docs/LIBERTIES.md, its `liberty`).
 *
 * HOW IT LOOKS FADED. Each building takes one tone of its material's family (the
 * sheet's pink brick, blue stone or yellow frame), with a third of its saturation gone
 * and pulled 42 % of the way to a pale grey (a tree keeps more of its green), so it is still there and still brick or frame but
 * never competes with a modelled house. Nothing is transparent: a faded stand-in is
 * opaque, so it costs one opaque draw per kind and sorts with nothing.
 *
 * HOW CHEAP. Five instanced meshes in all, at 2 to 26 triangles a building piece, sharing
 * one material: flat-roof boxes under a cornice, open boxes under a roof, gable ends, gable
 * roofs, pyramid roofs. No shadows cast or received, no textures: the facade is painted in
 * the shader from each instance's own size.
 *
 * WHAT IT GIVES WAY TO. A stand-in that a placed structure's footprint touches is
 * dropped at load, so a building drafted later on Indiana or Calumet replaces its
 * stand-in without anything here being regenerated. Every vertex is `reconstructed`
 * on the confidence channel (the heights are ours even where the outline is the
 * sheet's), so hiding reconstructed work takes the whole context city away.
 */

import * as THREE from 'three';

const FADE_TO = [0.86, 0.87, 0.88];   // a pale, faintly cool grey, in sRGB
const FADE = 0.42;                    // how far each colour goes toward it
const DESATURATE = 0.3;               // how much of its own saturation it loses first
const ROOF_TOP_SHADE = 0.86;          // a flat roof a little darker than its walls
// The faded streets (T-2491): a macadam-and-block grey-brown, faded like the buildings, the
// carriageway the grid's row_66 gives (38 ft), laid a few centimetres over the ground in pieces
// short enough to follow it.
const STREET = '#8a8174';
const STREET_LIFT_M = 0.05;
const STREET_PIECE_M = 25;
/** Past this from the scene's middle a far crown is left out (T-2493). */
const FAR_TREE_REACH_M = 2000;

const wx = (e) => e;
const wz = (n) => -n;

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/** One palette hex, faded: half its saturation gone, then most of the way to the pale grey. */
export function fadeHex(hex, jitter = 0, fade = FADE) {
  const n = parseInt(hex.replace('#', ''), 16);
  let rgb = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => c / 255);
  const y = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
  rgb = rgb.map((c) => c + (y - c) * DESATURATE);
  rgb = rgb.map((c, i) => c + (FADE_TO[i] - c) * fade);
  rgb = rgb.map((c) => Math.min(1, Math.max(0, c * (1 + jitter))));
  return new THREE.Color().setRGB(rgb[0], rgb[1], rgb[2], THREE.SRGBColorSpace);
}

/* -------------------------------------------------------------------------- */
/* unit geometries: x across (width), z along the long side (depth), y up      */
/* -------------------------------------------------------------------------- */

function geometry(positions, shades, { facade = 0, cornice = null } = {}) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  const colors = [];
  for (const s of shades) colors.push(s, s, s);
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  const n = positions.length / 3;
  g.setAttribute('_confidence', new THREE.Float32BufferAttribute(new Array(n).fill(1), 1));
  // T-2833: which faces the facade paints (1, a wall), and how far a cornice vertex
  // steps out and down from the unit box, in metres the shader works out per instance.
  g.setAttribute('aFacade', new THREE.Float32BufferAttribute(new Array(n).fill(facade), 1));
  g.setAttribute('aCorn', new THREE.Float32BufferAttribute(cornice ?? new Array(n * 4).fill(0), 4));
  g.computeVertexNormals();
  return g;
}

function quad(out, sh, a, b, c, d, s = 1) {
  out.push(...a, ...b, ...c, ...a, ...c, ...d);
  for (let i = 0; i < 6; i++) sh.push(s);
}

/**
 * Four walls from y 0 to 1, and with `top` a flat roof behind a cornice (T-2833): a
 * band that stands out from the wall head and is closed underneath, so a flat-roofed
 * stand-in reads as Chicago's brick flats and business blocks do, a box with a lid
 * and a shadow line, not a box. The cornice's reach and depth are metres, not
 * fractions of the box: each corner vertex carries the way out (`aCorn` xy), whether
 * it steps out (z) and whether it drops below the wall head (w), and the vertex
 * shader scales them by the building's height (CORNICE in FACADE_VERTEX).
 */
function boxGeometry(top, cornice = true) {
  const p = []; const s = [];
  const A = [-0.5, 0, 0.5]; const B = [0.5, 0, 0.5]; const C = [0.5, 0, -0.5]; const D = [-0.5, 0, -0.5];
  const up = (v) => [v[0], 1, v[2]];
  quad(p, s, A, B, up(B), up(A));
  quad(p, s, B, C, up(C), up(B));
  quad(p, s, C, D, up(D), up(C));
  quad(p, s, D, A, up(A), up(D));
  const walls = p.length / 3;
  if (!top) return geometry(p, s, { facade: 1 });
  if (!cornice) {
    // a plain lid: the phone's far rows (see `plainFar` in createContext)
    quad(p, s, up(A), up(B), up(C), up(D), ROOF_TOP_SHADE);
    const g = geometry(p, s);
    g.setAttribute('aFacade', new THREE.Float32BufferAttribute([...new Array(walls).fill(1), 0, 0, 0, 0, 0, 0], 1));
    return g;
  }
  const corn = new Array(walls * 4).fill(0);
  const facadeFlag = new Array(walls).fill(1);
  const corners = [A, B, C, D];
  const push = (list, shade) => {
    for (const v of list) {
      p.push(v.c[0], 1, v.c[2]);
      corn.push(Math.sign(v.c[0]), Math.sign(v.c[2]), v.out, v.down);
      facadeFlag.push(0);
    }
    for (let i = 0; i < list.length; i++) s.push(shade);
  };
  for (let i = 0; i < 4; i++) {
    const a = corners[i]; const b = corners[(i + 1) % 4];
    // soffit: the underside, from the wall out to the band's foot (facing down)
    push([{ c: a, out: 0, down: 1 }, { c: b, out: 1, down: 1 }, { c: a, out: 1, down: 1 },
      { c: a, out: 0, down: 1 }, { c: b, out: 0, down: 1 }, { c: b, out: 1, down: 1 }], 0.55);
    // the band's face (facing out)
    push([{ c: a, out: 1, down: 1 }, { c: b, out: 1, down: 0 }, { c: a, out: 1, down: 0 },
      { c: a, out: 1, down: 1 }, { c: b, out: 1, down: 1 }, { c: b, out: 1, down: 0 }], 1.06);
  }
  // the roof, out to the band's edge
  push([{ c: A, out: 1, down: 0 }, { c: B, out: 1, down: 0 }, { c: C, out: 1, down: 0 },
    { c: A, out: 1, down: 0 }, { c: C, out: 1, down: 0 }, { c: D, out: 1, down: 0 }], ROOF_TOP_SHADE);
  const g = geometry(p, s, { cornice: corn });
  g.setAttribute('aFacade', new THREE.Float32BufferAttribute(facadeFlag, 1));
  return g;
}

/** The two triangles closing a gable's ends, from the eave (y 0) to the ridge (y 1). */
function gableEndsGeometry() {
  const p = [-0.5, 0, 0.5, 0.5, 0, 0.5, 0, 1, 0.5, 0.5, 0, -0.5, -0.5, 0, -0.5, 0, 1, -0.5];
  return geometry(p, [1, 1, 1, 1, 1, 1]);
}

/** A gable's two slopes, the ridge along z, a little past the walls at the eaves. */
function gableRoofGeometry() {
  const p = []; const s = [];
  const o = 0.04;
  quad(p, s, [-0.5 - o, -o, 0.5 + o], [0, 1, 0.5 + o], [0, 1, -0.5 - o], [-0.5 - o, -o, -0.5 - o]);
  quad(p, s, [0, 1, 0.5 + o], [0.5 + o, -o, 0.5 + o], [0.5 + o, -o, -0.5 - o], [0, 1, -0.5 - o]);
  return geometry(p, s);
}

/** A pyramid (a tower's spire or a pavilion roof): four slopes to one point. */
function pyramidGeometry() {
  const a = [-0.5, 0, 0.5]; const b = [0.5, 0, 0.5]; const c = [0.5, 0, -0.5]; const d = [-0.5, 0, -0.5];
  const t = [0, 1, 0];
  return geometry([...a, ...b, ...t, ...b, ...c, ...t, ...c, ...d, ...t, ...d, ...a, ...t],
    new Array(12).fill(1));
}

/** The faded streets as one ribbon mesh: each segment cut into pieces that each take the
 *  ground's height at their ends, so a street follows the ground and the skirt beyond it. */
function streetGeometry(streets, at, width, ground, colour) {
  const p = []; const c = []; const conf = [];
  const half = width / 2;
  const push = (e, n) => { p.push(wx(e), ground(e, n) + STREET_LIFT_M, wz(n)); c.push(colour.r, colour.g, colour.b); conf.push(1); };
  for (const st of streets) {
    const e0 = st[at.e0]; const n0 = st[at.n0]; const e1 = st[at.e1]; const n1 = st[at.n1];
    const L = Math.hypot(e1 - e0, n1 - n0);
    if (!(L > 0)) continue;
    const ue = (e1 - e0) / L; const un = (n1 - n0) / L;
    const k = Math.max(1, Math.ceil(L / STREET_PIECE_M));
    for (let i = 0; i < k; i++) {
      const a = (L * i) / k; const b = (L * (i + 1)) / k;
      const ea = e0 + ue * a; const na = n0 + un * a; const eb = e0 + ue * b; const nb = n0 + un * b;
      // left and right of the line, looking along it (the right is east of a northward street)
      const lA = [ea - un * half, na + ue * half]; const rA = [ea + un * half, na - ue * half];
      const lB = [eb - un * half, nb + ue * half]; const rB = [eb + un * half, nb - ue * half];
      for (const q of [lA, rA, rB, lA, rB, lB]) push(q[0], q[1]);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(c, 3));
  g.setAttribute('_confidence', new THREE.Float32BufferAttribute(conf, 1));
  g.computeVertexNormals();
  return g;
}

/* -------------------------------------------------------------------------- */
/* the facade (T-2833)                                                          */
/* -------------------------------------------------------------------------- */

/**
 * WHAT A STAND-IN'S WALL CARRIES, painted by the shader and not modelled: storeys and
 * their rows of windows, a stone basement under a house's raised first floor, a door,
 * string courses, lintels; on a row, the party walls between its houses and each
 * house a slightly different brick; on a shop block, shop windows under the flats; on
 * a loft, the wide windows of the wholesale district; on a shed, a few high lights and
 * its doors. All of it is laid out in metres from the instance's own size, by the
 * kind its rule gives (`STYLE`), so a 6.5 m frame house has two storeys and a 40 m
 * loft block ten, with no triangle added. Past the distance a window is a pixel the
 * pattern gives way to its average, so the far city does not shimmer.
 *
 * What it rests on is the file's own rules (RULES in tools/build_context_1904.py:
 * storeys, materials, raised basements) and the period's building types; it claims
 * nothing about any one building, and the card still says it is a stand-in.
 */
const STYLE = {
  dwelling_masonry: 0, wing: 0, frame_dwelling: 0, printed: 0, block: 0, big_block: 0,
  house_row: 1, shops_block: 2, business_block: 3, loop_block: 3,
  outbuilding: 4, railway_shed: 4, porch: 5,
};
/** A row's houses: the 25 ft lot Chicago's subdivisions were laid in, give or take. */
const HOUSE_LOT_M = 7.6;

const FACADE_VERTEX_DECL = `
attribute float aFacade;
attribute vec4 aCorn;
attribute vec4 aStyle;
varying vec4 vFacA;
flat varying vec4 vFacB;
varying float vWall;
`;
// CORNICE: deeper and further out on a taller block, as an eight-storey loft's is.
const FACADE_VERTEX = `
#ifdef USE_INSTANCING
  vec3 fsc = vec3(length(instanceMatrix[0].xyz), length(instanceMatrix[1].xyz), length(instanceMatrix[2].xyz));
#else
  vec3 fsc = vec3(1.0);
#endif
  float corD = clamp(0.045 * fsc.y, 0.45, 1.6);
  float corO = clamp(0.03 * fsc.y, 0.28, 1.0);
  transformed.xz += aCorn.xy * aCorn.z * corO / fsc.xz;
  transformed.y -= aCorn.w * corD / fsc.y;
  bool xFace = abs(normal.x) > 0.5;
  vFacA = vec4(xFace ? position.z * fsc.z : position.x * fsc.x, position.y * fsc.y,
               0.5 * (xFace ? fsc.z : fsc.x), fsc.y);
  vFacB = aStyle;
  vWall = aFacade * (xFace ? 1.0 : -1.0);
`;
const FACADE_FRAGMENT_DECL = `
varying vec4 vFacA;
flat varying vec4 vFacB;
varying float vWall;
float fHash(float x) { return fract(sin(x * 91.3458) * 47453.5453); }
// a soft box: 1 inside |x| < h, 0 outside, a pixel's blur at the edge
float fBox(float x, float h, float aa) { return clamp((h - abs(x)) / max(aa, 1e-4) + 0.5, 0.0, 1.0); }
`;
const FACADE_FRAGMENT = `
if (vWall != 0.0 && vFacB.x < 4.5) {
  float kind = vFacB.x;
  float frame = mod(vFacB.y, 2.0);
  bool flatTop = vFacB.y > 1.5;
  float seed = vFacB.z;
  float unit = vFacB.w;
  bool longSide = vWall > 0.0;
  float along = vFacA.x; float h = vFacA.y; float halfL = vFacA.z; float H = vFacA.w;
  float aaX = max(fwidth(along), 1e-4); float aaY = max(fwidth(h), 1e-4);
  float pxm = max(aaX, aaY);
  // the fine pattern gives way to its average as a window shrinks to a pixel or two
  float crisp = 1.0 - smoothstep(0.30, 0.85, pxm);
  vec3 wall = diffuseColor.rgb;
  float isRow = step(0.5, kind) * step(kind, 2.5);
  // a row's houses (and a shop block's lots): which one, and where in it
  float local = along; float lotHalf = halfL; float lot = 0.0;
  if (unit > 0.5) {
    float x = along + halfL;
    lot = floor(x / unit);
    local = x - (lot + 0.5) * unit;
    lotHalf = 0.5 * unit;
    float tone = fHash(lot * 7.31 + seed * 113.0);
    wall *= mix(vec3(0.90, 0.93, 0.96), vec3(1.08, 1.03, 0.98), tone);
    // the party wall, a stripe of shadow at each house's edge
    float edge = lotHalf - abs(local);
    wall *= mix(1.0, 0.80, (1.0 - clamp(edge / max(aaX, 0.18), 0.0, 1.0)) * crisp);
  }
  // storeys
  float base = kind < 0.5 ? mix(1.1, 0.55, frame) : kind < 1.5 ? mix(1.1, 0.55, frame) : kind < 3.5 ? 0.35 : 0.25;
  float top = flatTop ? clamp(0.045 * H, 0.45, 1.6) + 0.45 : 0.55;
  float ground = kind > 1.5 && kind < 3.5 ? (kind < 2.5 ? 4.2 : 4.6) : 0.0;
  float body = max(1.0, H - base - top - ground);
  float storeyWant = kind > 2.5 && kind < 3.5 ? 3.9 : kind > 3.5 ? 99.0 : 3.4;
  float n = max(1.0, floor(body / storeyWant + 0.5));
  float st = body / n;
  float y = h - base - ground;
  float fl = floor(y / st);
  float yin = y - fl * st;
  // bays across the wall (or across each house)
  float bay = kind < 0.5 ? 2.4 + 0.5 * fHash(seed * 17.0) : kind < 2.5 ? lotHalf * 2.0 / 3.0 : kind < 3.5 ? 3.1 : 5.5;
  float span = unit > 0.5 ? lotHalf * 2.0 : halfL * 2.0;
  float nb = max(1.0, floor((span - 0.9) / bay));
  float xb = local + (mod(nb, 2.0) < 0.5 ? 0.5 * bay : 0.0);
  float bi = floor(xb / bay + 0.5);
  float xi = xb - bi * bay;
  float inSpan = fBox(local, nb * bay * 0.5, aaX);
  float ww = kind > 2.5 && kind < 3.5 ? 1.05 : kind > 3.5 ? 0.6 : 0.48;
  float wh = kind > 2.5 && kind < 3.5 ? 1.25 : kind > 3.5 ? 0.5 : 1.0;
  float sill = kind > 2.5 && kind < 3.5 ? 0.75 : 0.8;
  float win = 0.0; float lintel = 0.0;
  if (fl >= 0.0 && fl < n && kind < 3.5) {
    win = fBox(xi, ww, aaX) * fBox(yin - sill - wh, wh, aaY) * inSpan;
    lintel = fBox(xi, ww + 0.12, aaX) * fBox(yin - sill - 2.0 * wh - 0.1, 0.1, aaY) * inSpan * (1.0 - frame);
  }
  if (kind > 3.5 && kind < 4.5) {
    // a shed: high small lights, and its doors at the middle of each long side
    float yl = h - H * 0.62;
    win = fBox(xi, ww, aaX) * fBox(yl, wh, aaY) * inSpan;
    float door = fBox(along, longSide ? 1.4 : 0.0, aaX) * fBox(h - 1.6, 1.6, aaY);
    win = max(win, door);
  }
  // the ground storey of a shop block: shop windows between thin piers
  if (kind > 1.5 && kind < 2.5 && h > base && h < base + ground) {
    float sx = local; float sy = h - base;
    win = max(win, fBox(sx, lotHalf - 0.45, aaX) * fBox(sy - 1.9, 1.35, aaY));
  }
  if (kind > 2.5 && kind < 3.5 && h > base && h < base + ground) {
    win = max(win, fBox(xi, 1.2, aaX) * fBox(h - base - 2.3, 1.6, aaY) * inSpan);
  }
  // a door: on a house's end, in each row house's first bay on its long sides, at
  // the top of its stone stoop
  float door = 0.0; float stoop = 0.0;
  if (kind < 0.5 && !longSide) {
    float dx = local - (nb - 1.0) * 0.5 * bay * (fHash(seed * 5.0) < 0.5 ? -1.0 : 1.0);
    door = fBox(dx, 0.55, aaX) * fBox(h - base - 1.25, 1.25, aaY) * step(1.5, nb);
    stoop = fBox(dx, 0.85, aaX) * fBox(h - base * 0.5, base * 0.5, aaY) * step(1.5, nb);
    win *= 1.0 - fBox(dx, 0.7, aaX) * step(fl, 0.5) * step(1.5, nb);
  }
  if (kind > 0.5 && kind < 1.5 && longSide) {
    float dx = local - bay * (fHash(lot * 3.1 + seed) < 0.5 ? -1.0 : 1.0);
    door = fBox(dx, 0.55, aaX) * fBox(h - base - 1.25, 1.25, aaY);
    stoop = fBox(dx, 0.85, aaX) * fBox(h - base * 0.5, base * 0.5, aaY);
    win *= 1.0 - fBox(dx, 0.7, aaX) * step(fl, 0.5);
  }
  // the glass: dark, a little of the sky in its upper sash; a two-over-two sash's
  // bars and meeting rail where the window is big enough to show them
  float wy = clamp((yin - sill) / (2.0 * wh), 0.0, 1.0);
  vec3 glass = wall * vec3(0.28, 0.31, 0.37) + vec3(0.010, 0.013, 0.018) + vec3(0.03, 0.035, 0.045) * wy;
  float sash = (fBox(xi, 0.035, aaX) + fBox(yin - sill - wh, 0.04, aaY)) * step(fl, n - 0.5) * step(-0.5, fl)
    * step(kind, 2.5) * (1.0 - smoothstep(0.03, 0.08, pxm));
  glass = mix(glass, wall * 0.9, clamp(sash, 0.0, 1.0) * win);
  vec3 doorCol = wall * vec3(0.42, 0.36, 0.31);
  vec3 c = wall;
  // a stone basement, a course at each floor, a stone lintel over each window
  if (frame < 0.5 && kind < 3.5) {
    c *= mix(1.0, 0.86, fBox(h - base * 0.5, base * 0.5, aaY));
    float course = fBox(yin, 0.07, aaY) * step(0.5, fl) * step(fl, n - 0.5);
    c = mix(c, c * 1.12, course * crisp);
    c = mix(c, mix(c, vec3(0.62, 0.60, 0.55), 0.45), lintel);
  } else if (frame > 0.5) {
    // a frame house: corner boards and window casings in a lighter paint
    float cornerB = 1.0 - fBox(along, halfL - 0.18, aaX);
    c = mix(c, c * 1.15, cornerB * crisp);
    float casing = fBox(xi, ww + 0.09, aaX) * fBox(yin - sill - wh, wh + 0.09, aaY) * inSpan * step(fl, n - 0.5);
    c = mix(c, c * 1.18, casing * crisp);
  }
  c = mix(c, mix(c, vec3(0.58, 0.56, 0.52), 0.55), stoop * crisp);
  c = mix(c, glass, win);
  c = mix(c, doorCol, door);
  // what a far wall averages to: its glass share darkens it a little
  float cover = clamp((2.0 * ww * 2.0 * wh) / (bay * st), 0.0, 0.5);
  vec3 far = mix(wall * mix(1.0, 0.9, step(frame, 0.5)), glass, cover * 0.8);
  diffuseColor.rgb = mix(far, c, crisp);
}
`;

/** Hook the facade onto a material (before the confidence view's own hook). */
function patchFacade(material) {
  const prior = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    if (typeof prior === 'function' && prior !== THREE.Material.prototype.onBeforeCompile) prior(shader, renderer);
    shader.vertexShader = FACADE_VERTEX_DECL + shader.vertexShader.replace(
      '#include <begin_vertex>', `#include <begin_vertex>\n${FACADE_VERTEX}`);
    shader.fragmentShader = FACADE_FRAGMENT_DECL + shader.fragmentShader.replace(
      '#include <roughnessmap_fragment>', `${FACADE_FRAGMENT}\n#include <roughnessmap_fragment>`);
  };
  material.customProgramCacheKey = () => 'context-facade-t2833';
  return material;
}

/* -------------------------------------------------------------------------- */
/* giving way to real buildings                                                */
/* -------------------------------------------------------------------------- */

function inPoly(e, n, pts) {
  let ok = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const [xi, yi] = pts[i]; const [xj, yj] = pts[j];
    if ((yi > n) !== (yj > n) && e < xi + ((n - yi) * (xj - xi)) / (yj - yi)) ok = !ok;
  }
  return ok;
}

function corners(e, n, w, d, bearing, grow = 0) {
  const t = (bearing * Math.PI) / 180;
  const u = [Math.sin(t), Math.cos(t)];
  const v = [u[1], -u[0]];
  const hd = d / 2 + grow; const hw = w / 2 + grow;
  return [[1, 1], [1, -1], [-1, -1], [-1, 1]].map(([su, sv]) => [
    e + su * u[0] * hd + sv * v[0] * hw, n + su * u[1] * hd + sv * v[1] * hw]);
}

/** Footprints with their plan boxes, for a fast first test. */
function indexFootprints(footprints) {
  return (footprints ?? []).filter((f) => f.pts?.length >= 3).map((f) => {
    const es = f.pts.map((p) => p[0]); const ns = f.pts.map((p) => p[1]);
    return { pts: f.pts, e0: Math.min(...es), e1: Math.max(...es), n0: Math.min(...ns), n1: Math.max(...ns) };
  });
}

/** True when a placed structure's footprint touches this rectangle (grown by `grow` m). */
function touchesStructure(fps, e, n, w, d, bearing, grow = 1.0) {
  const r = Math.hypot(w, d) / 2 + grow;
  const rect = corners(e, n, w, d, bearing, grow);
  for (const f of fps) {
    if (e + r < f.e0 || e - r > f.e1 || n + r < f.n0 || n - r > f.n1) continue;
    if (inPoly(e, n, f.pts) || rect.some(([x, y]) => inPoly(x, y, f.pts))) return true;
    if (f.pts.some(([x, y]) => inPoly(x, y, rect))) return true;
  }
  return false;
}

/* -------------------------------------------------------------------------- */
/* the layer                                                                    */
/* -------------------------------------------------------------------------- */

/**
 * @param {object} o
 * @param {URL|null} o.dataBase   where data/ lives; null (a scene that does not list
 *                                `context`) draws nothing
 * @param {string} o.sceneId
 * @param {object} o.terrain      the scene's terrain (surfaceHeight, grid)
 * @param {Array}  [o.footprints] placed structures' plan footprints ({pts}) to give way to
 * @param {object} [o.confidence] the confidence view
 * @param {string} [o.detail]     full | balanced | light: light draws a nearer ring and fewer trees
 * @param {string[]} [o.problems]
 */
export async function createContext({
  dataBase, sceneId, terrain, footprints = [], confidence = null, detail = 'full', problems = [],
} = {}) {
  const group = new THREE.Group();
  group.name = 'context';
  const out = {
    group, doc: null,
    census: { buildings: 0, trees: 0, dropped: 0, triangles: 0, meshes: 0 },
    pickAt: () => null, setSeason: () => {}, treeStems: () => [], dispose: () => {},
  };
  if (!dataBase || !terrain) return out;
  let doc;
  try {
    doc = await getJSON(new URL(`context/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`context city: ${err.message} — none is drawn`);
    return out;
  }
  out.doc = doc;
  const F = doc.fields?.buildings ?? [];
  const at = Object.fromEntries(F.map((k, i) => [k, i]));
  const T = Object.fromEntries((doc.fields?.trees ?? []).map((k, i) => [k, i]));
  const enums = doc.enums ?? {};
  const palette = doc.palette ?? {};
  const fps = indexFootprints(footprints);

  // Past the measured box the ground is the skirt, which carries the box's edge outward,
  // so a stand-in out there stands on the edge's height.
  const g = terrain.grid ?? null;
  const ground = (e, n) => {
    if (!terrain.contextCoast && terrain.inBounds?.(e, n) === false && g) {
      const e0 = g.originE; const n0 = g.originN;
      const e1 = e0 + 700; const n1 = n0 + 900;
      return terrain.surfaceHeight(Math.min(Math.max(e, e0), e1), Math.min(Math.max(n, n0), n1));
    }
    return terrain.surfaceHeight(e, n);
  };

  // Light detail (a phone's default) keeps the ring nearer: past `reach` from the scene's
  // middle, projected stand-ins thin out and their trees go.
  const light = detail === 'light';
  const mid = [1405, -3350];
  const reach = light ? 520 : Infinity;
  const far = (e, n) => Math.hypot(e - mid[0], n - mid[1]) > reach;
  // T-2493: a far crown past FAR_TREE_REACH_M stands in at least 96 % haze (world.js
  // HAZE_DENSITY: 1 - exp(-(0.00089 × 2000)²)) and is not drawn: 5,300 of the 6,532 far
  // crowns, 42k triangles at the 1904 spawn. The stand-in buildings out there stay, so
  // the skyline still runs out to the haze.
  const hazeTree = (e, n) => Math.hypot(e - mid[0], n - mid[1]) > FAR_TREE_REACH_M;

  const kinds = { box: [], plain: [], walls: [], ends: [], gable: [], pyramid: [] };
  // T-2833: on light detail a row past the near ring keeps one lid and one ridge, as
  // before: its cornice and its houses' own gables are 120k triangles a phone draws
  // at the haze's edge, where they are a pixel or two. Its walls are painted the same.
  const plainFar = light;
  const rows = [];
  let dropped = 0;
  const projectSrc = (enums.src ?? []).indexOf('project');
  for (const b of doc.buildings ?? []) {
    const e = b[at.e]; const n = b[at.n]; const w = b[at.width_m]; const d = b[at.depth_m];
    const bearing = b[at.bearing_deg];
    if (touchesStructure(fps, e, n, w, d, bearing)) { dropped++; continue; }
    // On light detail the near ring's one-to-a-lot houses stop at `reach`; the rows of lots past
    // the ring (lod 1, T-2491) stay, so a phone still sees the city run out to the haze.
    if (b[at.src] === projectSrc && !b[at.lod] && far(e, n)) continue;
    const roof = enums.roof?.[b[at.roof]] ?? 'flat';
    const cs = corners(e, n, w, d, bearing);
    const y0 = Math.min(...cs.map(([x, y]) => ground(x, y)), ground(e, n)) - 0.15;
    const yc = ground(e, n);
    const eave = b[at.eave_m] + (yc - y0);
    const rec = { e, n, w, d, bearing, y0, eave, rise: b[at.rise_m], roof, row: b };
    // T-2833: how the facade paints it (STYLE), and a row's houses
    const rule = enums.rule?.[b[at.rule]] ?? '';
    const kind = STYLE[rule] ?? 0;
    const frame = (enums.material?.[b[at.material]] ?? 'brick') === 'frame';
    const lots = kind === 1 || kind === 2 ? Math.max(1, Math.round(d / HOUSE_LOT_M)) : 0;
    rec.style = [kind, (frame ? 1 : 0) + (roof === 'flat' ? 2 : 0), ((Math.abs(e * 0.731 + n * 0.377)) % 1), lots ? d / lots : 0];
    rows.push(rec);
    const plain = plainFar && b[at.lod];
    if (roof === 'flat') (plain ? kinds.plain : kinds.box).push(rec);
    else if (kind === 1 && roof === 'gable' && !plain) {
      // A row of houses under one ridge read as a barn. Each house takes its own roof
      // instead, its gable to the street, as the city's frame and brick cottages stood.
      kinds.walls.push(rec);
      const t = (bearing * Math.PI) / 180;
      const ue = Math.sin(t); const un = Math.cos(t);
      const unit = d / lots;
      for (let k = 0; k < lots; k++) {
        const s = -d / 2 + unit * (k + 0.5);
        const house = { e: e + ue * s, n: n + un * s, w: unit, d: w, bearing: bearing + 90, y0, eave,
          rise: Math.min(rec.rise, unit * (0.38 + 0.12 * ((k * 0.618 + rec.style[2]) % 1))), roof, row: b };
        kinds.ends.push(house); kinds.gable.push(house);
      }
    } else {
      kinds.walls.push(rec);
      if (roof === 'gable') { kinds.ends.push(rec); kinds.gable.push(rec); } else kinds.pyramid.push(rec);
    }
  }
  // T-2833: the trees are handed to the parkway's grown elms (street-trees.js), which
  // draw them with their own crowns, season and setting. Which ones, by detail: light
  // keeps the near ring's and two in three of its projected trees, as the crowns did.
  const treeSets = new Map();
  const treeStems = (level) => {
    if (treeSets.has(level)) return treeSets.get(level);
    const thin = level === 'light';
    const farFor = (e, n) => thin && Math.hypot(e - mid[0], n - mid[1]) > 520;
    const list = [];
    for (const t of doc.trees ?? []) {
      const e = t[T.e]; const n = t[T.n]; const r = t[T.crown_r_m];
      if (thin && (farFor(e, n) || t[T.lod] || t[T.src] === 1 && ((e * 7.3 + n * 3.1) % 3 + 3) % 3 < 1)) continue;
      if (t[T.lod] && hazeTree(e, n)) continue;
      if (touchesStructure(fps, e, n, r, r, 0, 0)) continue;
      list.push({ e, n, y: ground(e, n), h: t[T.height_m] });
    }
    treeSets.set(level, list);
    return list;
  };
  out.treeStems = treeStems;

  const material = patchFacade(new THREE.MeshStandardMaterial({
    color: 0xffffff, vertexColors: true, roughness: 1, metalness: 0, flatShading: true,
  }));
  confidence?.patch(material);

  const m4 = new THREE.Matrix4(); const q = new THREE.Quaternion(); const Y = new THREE.Vector3(0, 1, 0);
  const pos = new THREE.Vector3(); const scl = new THREE.Vector3();
  // A stand-in's tone varies a little from its neighbour's, seeded by where it stands.
  const jitter = (e, n) => ((Math.sin(e * 12.9898 + n * 78.233) * 43758.5453) % 1) * 0.06;
  const wallColour = (r) => {
    const fam = palette[enums.material?.[r.row[at.material]] ?? 'brick'] ?? ['#a0a0a0'];
    return fadeHex(fam[r.row[at.tone] % fam.length], jitter(r.e, r.n));
  };
  const roofColour = (r) => {
    const fam = palette.roof ?? ['#555555'];
    return fadeHex(fam[r.row[at.roof_tone] % fam.length], jitter(r.n, r.e));
  };
  const meshes = [];
  const add = (geo, list, place, colour, name, mat = material) => {
    if (!list.length) { geo.dispose(); return; }
    if (mat === material) {
      const st = new Float32Array(list.length * 4);
      list.forEach((r, i) => st.set(r.style ?? [5, 0, 0, 0], i * 4));
      geo.setAttribute('aStyle', new THREE.InstancedBufferAttribute(st, 4));
    }
    const mesh = new THREE.InstancedMesh(geo, mat, list.length);
    mesh.name = `context:${name}`;
    list.forEach((r, i) => {
      place(r);
      m4.compose(pos, q, scl);
      mesh.setMatrixAt(i, m4);
      mesh.setColorAt(i, colour(r));
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.computeBoundingSphere();
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.userData.rows = list;
    group.add(mesh);
    meshes.push(mesh);
    out.census.triangles += (geo.getAttribute('position').count / 3) * list.length;
  };
  const body = (r) => { q.setFromAxisAngle(Y, (-r.bearing * Math.PI) / 180); pos.set(wx(r.e), r.y0, wz(r.n)); scl.set(r.w, r.eave, r.d); };
  const top = (r) => { q.setFromAxisAngle(Y, (-r.bearing * Math.PI) / 180); pos.set(wx(r.e), r.y0 + r.eave, wz(r.n)); scl.set(r.w, Math.max(r.rise, 0.5), r.d); };
  add(boxGeometry(true), kinds.box, body, wallColour, 'flat');
  add(boxGeometry(true, false), kinds.plain, body, wallColour, 'flat-plain');
  add(boxGeometry(false), kinds.walls, body, wallColour, 'walls');
  add(gableEndsGeometry(), kinds.ends, top, wallColour, 'gable-ends');
  add(gableRoofGeometry(), kinds.gable, top, roofColour, 'gable-roofs');
  add(pyramidGeometry(), kinds.pyramid, top, roofColour, 'pyramid-roofs');

  // The faded streets: one mesh, under any street the grid draws (the tool keeps them apart).
  const S = Object.fromEntries((doc.fields?.streets ?? []).map((k, i) => [k, i]));
  let streetMesh = null; let streetMaterial = null;
  if ((doc.streets ?? []).length) {
    const width = doc.projection?.network?.carriageway_m ?? 11.58;
    const geo = streetGeometry(doc.streets, S, width, ground, fadeHex(STREET));
    streetMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff, vertexColors: true, roughness: 1, metalness: 0,
      polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1,
    });
    confidence?.patch(streetMaterial);
    streetMesh = new THREE.Mesh(geo, streetMaterial);
    streetMesh.name = 'context:streets';
    streetMesh.receiveShadow = true;
    streetMesh.castShadow = false;
    group.add(streetMesh);
    out.census.triangles += geo.getAttribute('position').count / 3;
    out.census.street_km = Math.round((doc.counts?.street_km ?? 0) * 10) / 10;
  }

  out.census.buildings = rows.length;
  out.census.trees = treeStems(detail).length;
  out.census.dropped = dropped;
  out.census.meshes = meshes.length + (streetMesh ? 1 : 0);

  // A pick answers with what the stand-in is and what it rests on.
  const raycaster = new THREE.Raycaster();
  const rules = doc.rules ?? {};
  const sheetName = (s) => doc.sheet_names?.[s] ?? `Sanborn 1911 vol. 3 sheet ${s}`;
  const srcWords = (s) => (s === 'project'
    ? 'projected: no map of this ground is in hand, so the street, the lot and the building are laid out on the grid the section corners and the traced maps measure, in the use the 1904 city gave the block'
    : `read off ${sheetName(s)}, the smallest rectangle holding the part the map draws`);
  const cardFor = (r) => {
    const src = enums.src?.[r.row[at.src]] ?? 'project';
    const mat = enums.material?.[r.row[at.material]] ?? 'brick';
    const rule = enums.rule?.[r.row[at.rule]] ?? '';
    const sourceId = src === 'project' ? null
      : (doc.sheet_sources?.[src] ?? (doc.sources ?? []).find((s) => s.endsWith(`sheet_${src}`)));
    const why = rule === 'printed' ? 'the figure the sheet prints for it' : (rules[rule]?.why ?? '');
    return {
      id: `context:${r.e},${r.n}`,
      sidecar: {
        name: src === 'project' ? 'A stand-in for the city around Prairie Avenue' : `A ${mat} building, as ${sheetName(src)} draws it`,
        phase: null,
        change_note: `A faded stand-in, not a model: ${srcWords(src)}. `
          + `${Math.round(r.w)} by ${Math.round(r.d)} m, ${Math.round(r.row[at.eave_m])} m to the eaves (${why}). `
          + `Prairie Avenue's buildings are the ones in full colour.`,
        placement: {
          symbolic_location: src === 'project' ? 'Projected past the maps in hand' : sheetName(src),
          position_confidence: src === 'project' ? 'reconstructed' : 'inferred',
          position_sources: sourceId ? [sourceId] : [],
          position_note: doc.tiers?.[src === 'project' ? 'projection' : 'sheet_outline'] ?? '',
        },
        attributes: {
          material: {
            value: mat, confidence: src === 'project' ? 'reconstructed' : 'inferred',
            sources: sourceId ? [sourceId] : [],
            note: src === 'project' ? `Drawn in the measured mix of the traced sheets (${JSON.stringify(doc.projection?.material_mix ?? {})}).` : doc.tiers?.sheet_material ?? '',
          },
          height_and_roof: {
            value: `${Math.round(r.row[at.eave_m])} m to the eaves, ${enums.roof?.[r.row[at.roof]] ?? ''} roof`,
            confidence: 'reconstructed', sources: [], note: why,
          },
        },
        citations: [],
        research_note: `Context city, ${doc.ticket}${doc.extended_by ? ` and ${doc.extended_by}` : ''} (data/context/${sceneId}.json); `
          + `docs/LIBERTIES.md ${doc.liberty}${doc.liberty_streets ? ` and ${doc.liberty_streets}` : ''}.`,
      },
    };
  };
  out.pickAt = (ndc, camera) => {
    if (!camera || !meshes.length) return null;
    raycaster.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    raycaster.far = Math.max(600, camera.position.y * 4);
    const hits = raycaster.intersectObjects(meshes, false);
    const hit = hits.find((h) => h.instanceId != null);
    if (!hit) return null;
    const r = hit.object.userData.rows[hit.instanceId];
    const record = cardFor(r);
    return { id: record.id, record, point: hit.point.clone(), distance: hit.distance };
  };
  out.dispose = () => {
    for (const m of meshes) { m.geometry.dispose(); m.dispose?.(); }
    streetMesh?.geometry.dispose();
    streetMaterial?.dispose();
    material.dispose();
  };
  return out;
}
